import os

CACHE_PATH = "saju_cache.json"

def create_saju_key(year, month, day, hour, gender):
    return f"{year}-{month}-{day}-{hour}-{gender}"

def save_cache(key, data):
    cache = {}
    if os.path.exists(CACHE_PATH):
        try:
            with open(CACHE_PATH, "r", encoding="utf-8") as f:
                cache = json.load(f)
        except:
            pass
    cache[key] = data
    try:
        with open(CACHE_PATH, "w", encoding="utf-8") as f:
            json.dump(cache, f, ensure_ascii=False)
    except:
        pass

def load_cache(key):
    if not os.path.exists(CACHE_PATH):
        return None
    try:
        with open(CACHE_PATH, "r", encoding="utf-8") as f:
            cache = json.load(f)
        return cache.get(key)
    except:
        return None

