def get_sam_hap(pils):
    jjs = set(p["jj"] for p in pils)
    results = []
    for combo, (name, oh, desc) in SAM_HAP_MAP.items():
        if combo.issubset(jjs):
            results.append({"type":"?쇳빀(訝됧릦)","name":name,"oh":oh,"desc":desc,
                "narrative":f"?뙚 [?쇳빀] {desc}?쇰줈 {name}???뺤꽦! {oh} 湲곗슫??紐낅컲 ?꾩껜瑜?媛뺥솕?섎땲??"})
    if not results:
        for combo, (name, oh, hap_type) in BAN_HAP_MAP.items():
            if combo.issubset(jjs):
                results.append({"type":"諛섑빀(?듿릦)","name":name,"oh":oh,"desc":hap_type,
                    "narrative":f"??[諛섑빀] {name}??留븐뼱??{oh} ?ㅽ뻾??寃곗냽?μ씠 ?앷린由щ씪."})
    for combo, (name, oh, hap_type) in BANG_HAP_MAP.items():
        if combo.issubset(jjs):
            results.append({"type":"諛⑺빀(?밧릦)","name":name,"oh":oh,"desc":hap_type,
                "narrative":f"?㎛ [諛⑺빀] {name}???몃젰???뺤꽦?섏뼱 {oh} ?ㅽ뻾??媛뺤꽦?댁?由щ씪."})
    return results


