def get_gongmang(pils):
    """怨듬쭩(令뷰벙) 怨꾩궛"""
    nyon_cg = pils[3]["cg"]
    gong_pair = GONGMANG_TABLE.get(nyon_cg, ("",""))
    result = {"怨듬쭩_吏吏": gong_pair, "?대떦_湲곕뫁": []}
    for i, p in enumerate(pils):
        label = ["?쒖＜","?쇱＜","?붿＜","?꾩＜"][i]
        if p["jj"] in gong_pair:
            result["?대떦_湲곕뫁"].append({
                "湲곕뫁": label, "吏吏": p["jj"],
                "desc": GONGMANG_JJ_DESC.get(p["jj"],""),
            })
    return result


