def get_nabjin(cg, jj):
    pillar = cg + jj
    for k, v in NABJIN_MAP.items():
        if pillar in k:
            name, oh, desc = v
            return {"name":name,"oh":oh,"desc":desc}
    return {"name":"誘몄긽","oh":"","desc":""}


