import json

def get_ai_interpretation(prompt_text, api_key="", system="?뱀떊? 40??寃쎈젰???쒓뎅 ?꾪넻 ?ъ＜紐낅━ ?꾨Ц媛?낅땲??", max_tokens=2000, groq_key=""):
    """AI ?댁꽍 ?붿껌 ??Anthropic ?먮뒗 Groq ?좏깮"""
    import requests

    # Groq ?곗꽑 (鍮좊쫫, 臾대즺)
    if groq_key and groq_key.strip():
        try:
            headers = {
                "Authorization": f"Bearer {groq_key.strip()}",
                "Content-Type": "application/json"
            }
            data = {
                "model": "llama-3.3-70b-versatile",
                "messages": [
                    {"role": "system", "content": system},
                    {"role": "user",   "content": prompt_text}
                ],
                "max_tokens": max_tokens,
                "temperature": 0.7
            }
            resp = requests.post("https://api.groq.com/openai/v1/chat/completions",
                                 headers=headers, json=data, timeout=60)
            if resp.status_code == 200:
                return resp.json()["choices"][0]["message"]["content"]
            else:
                return f"[Groq ?ㅻ쪟 {resp.status_code}]: {resp.text[:200]}"
        except Exception as e:
            return f"[Groq ?곌껐 ?ㅻ쪟: {e}]"

    # Anthropic fallback
    if api_key and api_key.strip():
        try:
            headers = {
                "x-api-key": api_key.strip(),
                "anthropic-version": "2023-06-01",
                "content-type": "application/json"
            }
            data = {
                "model": "claude-sonnet-4-6",
                "max_tokens": max_tokens,
                "system": system,
                "messages": [{"role": "user", "content": prompt_text}]
            }
            resp = requests.post("https://api.anthropic.com/v1/messages",
                                 headers=headers, json=data, timeout=60)
            if resp.status_code == 200:
                return resp.json()["content"][0]["text"]
            else:
                return f"[Anthropic ?ㅻ쪟 {resp.status_code}]: {resp.text[:200]}"
        except Exception as e:
            return f"[Anthropic ?곌껐 ?ㅻ쪟: {e}]"

    return ""  # ?????놁쑝硫?鍮?臾몄옄??


