def render_pillars(pils):
    """?ъ＜ 湲곕뫁 ?쒖떆"""
    labels = ["????", "????", "????", "??亮?"]
    cols = st.columns(4)
    for i, (p, label) in enumerate(zip(pils, labels)):
        cg = p["cg"]
        jj = p["jj"]
        cg_kr = CG_KR[CG.index(cg)]
        jj_kr = JJ_KR[JJ.index(jj)]
        jj_an = JJ_AN[JJ.index(jj)]
        oh_cg = OH.get(cg, "")
        oh_jj = OH.get(jj, "")
        emoji_cg = OHE.get(oh_cg, "")
        emoji_jj = OHE.get(oh_jj, "")
        
        with cols[i]:
            st.markdown(f"""
            <div class="pillar-box">
                <div style="font-size:11px;color:#888;margin-bottom:4px">{label}</div>
                <div style="font-size:28px;font-weight:700;color:#8B6914">{cg}</div>
                <div style="font-size:11px;color:#999">{cg_kr} 쨌 {emoji_cg}{oh_cg}</div>
                <div style="font-size:30px;font-weight:700;color:#7b5f2a;margin-top:6px">{jj}</div>
                <div style="font-size:11px;color:#999">{jj_kr} 쨌 {emoji_jj}{oh_jj}</div>
                <div style="font-size:10px;color:#bbb;margin-top:4px">{jj_an}??/div>
            </div>""", unsafe_allow_html=True)


